                    <h2 id="endpoints-POSTapi-customer-auth-registration">POST api/customer/auth/registration</h2>

<p>
</p>



<span id="example-requests-POSTapi-customer-auth-registration">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "localhost/api/customer/auth/registration" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "first_name=architecto"\
    --form "last_name=architecto"\
    --form "email=zbailey@example.net"\
    --form "phone=iyvdljn"\
    --form "password=gxwmi/#iw/"\
    --form "identification_type=nid"\
    --form "profile_image=@C:\Users\MHars\AppData\Local\Temp\php6B0B.tmp" \
    --form "identity_images[]=@C:\Users\MHars\AppData\Local\Temp\php6B1C.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "localhost/api/customer/auth/registration"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('first_name', 'architecto');
body.append('last_name', 'architecto');
body.append('email', 'zbailey@example.net');
body.append('phone', 'iyvdljn');
body.append('password', 'gxwmi/#iw/');
body.append('identification_type', 'nid');
body.append('profile_image', document.querySelector('input[name="profile_image"]').files[0]);
body.append('identity_images[]', document.querySelector('input[name="identity_images[]"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

