    "localhost/api/driver/update/profile" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "first_name=architecto"\
    --form "last_name=architecto"\
    --form "service=architecto"\
    --form "profile_image=@C:\Users\MHars\AppData\Local\Temp\phpB6FD.tmp" \
    --form "identity_images[]=@C:\Users\MHars\AppData\Local\Temp\phpB6FE.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "localhost/api/driver/update/profile"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('first_name', 'architecto');
body.append('last_name', 'architecto');
body.append('service', 'architecto');
body.append('profile_image', document.querySelector('input[name="profile_image"]').files[0]);
body.append('identity_images[]', document.querySelector('input[name="identity_images[]"]').files[0]);

fetch(url, {
    method: "PUT",
    headers,
    body,
